// test-adr: 029, 010
// Issue #1491, the duplicate half: two files that both name ONE included
// function-as-type must not each export its `_fp` typedef.
//
// When the typedef went wherever the type was NAMED, `consumer-a.h` and
// `consumer-b.h` each defined `sharedWork_fp`, and this file -- which includes
// both -- saw the same typedef twice. gcc accepts that as an extension, so the
// suite stayed green; `-std=c99 -pedantic-errors` rejects it outright:
//
//     error: redefinition of typedef 'sharedWork_fp' [-Wpedantic]
//
// The generated C is the certification artifact, so "gcc happened not to
// complain" is not the standard.
//
// The rule that fixes it is the one C libraries already follow: a header
// typedefs the callback types ITS OWN API uses -- POSIX's signal-handler typedef,
// `curl_write_callback` -- and nothing else. `stdlib.h` does not typedef
// `qsort`'s comparator; it writes the pointer inline, because no caller needs
// to name it. Here neither consumer's public interface mentions the type, so
// each keeps its typedef in its own `.c`, where a duplicate across separate
// translation units is legal and ordinary.
//
// This file exports `combined()` so that it HAS a header at all. Without one,
// `selfIncludeAdded` is false and the `.c` emits the typedef whatever the
// ownership rule says -- the decision under test is unreachable, and a fixture
// built on it passes either way. That was the first version of this file.
//
// The assertion is in THIS file's own snapshot, deliberately. The consumers'
// headers are helpers -- not snapshot-compared -- and gcc accepts a duplicate
// typedef as an extension, so a fixture resting on either could not fail. So
// `main` also names the type locally: under the correct rule the typedef lands
// in `two-consumers.test.c`, and if header ownership goes back to "whoever
// names it" it moves into `two-consumers.test.h` instead. Both files are
// compared, so the regression reddens this fixture rather than only dirtying a
// helper header.
// `dup-lib.cnx` is NOT included here. It used to be, purely so its object got
// linked -- the harness linked a fixture's DIRECT includes only, so a symbol
// reached through the consumers had nothing defining it at link time. That was
// a workaround for #1508, recorded as one in this comment; the harness now
// links the transitive closure and the redundant include is gone. `sharedWork`
// still reaches this file through both consumers, which is the shape the
// duplicate-typedef decision is actually about.
#include "consumer-a.h"
#include "consumer-b.h"

#include <stdint.h>

// ADR-044: Overflow helper functions
#include <limits.h>

/* ADR-044 / Issue #94: the second parameter is the WIDER type, not the value type.
   Narrowing it first would let an out-of-range operand truncate INTO range and defeat
   the check: cnx_clamp_add_u8(0, 256) must saturate to 255, but (uint8_t)256 is 0, so a
   uint8_t parameter would return 0 -- the opposite of saturation. */

static inline uint32_t cnx_clamp_add_u32(uint32_t a, uint64_t b) {
    if (b > (uint64_t)(UINT32_MAX - a)) return UINT32_MAX;
    return (uint32_t)(a + (uint32_t)b);
}

// Public, so this file gets a header and the ownership decision is reachable.

typedef uint32_t (*sharedWork_fp)(void);

uint32_t combined(void) {
    return cnx_clamp_add_u32(useA(), useB());
}

int main(void) {
    const uint32_t a = useA();
    if (a != 3) {
        return 1U;
    }
    const uint32_t b = useB();
    if (b != 3) {
        return 2U;
    }
    if (a != b) {
        return 3U;
    }
    const sharedWork_fp viaMain = sharedWork;
    const uint32_t m = viaMain();
    if (m != 3) {
        return 4U;
    }
    return 0U;
}
